def validate(d):
    if d!=EXPECTED:raise ValueError('reviewed R01 draft changed')
    c=d['candidate']
    if [len(c[k]) for k in ['propositions','voices','evidence_units','links','routes']]!=[7,7,7,7,0]:raise ValueError('inventory')
    for p,v,e,l in zip(c['propositions'],c['voices'],c['evidence_units'],c['links']):
        if l['proposition_ref']!=p['staging_key'] or v['proposition_ref']!=p['staging_key'] or l['evidence_unit_ref']!=e['staging_key']:raise ValueError('links')
